// Signed requests bind the existing cloud identity to a durable test grant.
// Execution state remains in M10's plan/outbox and the lab's physical journal.
import {createHash,verify} from 'node:crypto';
import {publicKeyFromBase64} from './cloud-session-proof.js';
import {assertCloudSessionCurrent} from './cloud-session-lifecycle.js';
import {currentCloudGrant,requireCloudAccess,cloudStableAgentId} from './cloud-project-access.js';
import {planLabTest,ensureLabTestingSchema} from './lab-testing.js';
import {resolveLabRepoTestSelection} from './lab-repo-test-selector.js';
import {getLabDispatch} from './lab-shared-dispatch-outbox.js';
import {labProofForPlan} from './lab-proof-history.js';
import {retainRelayReceipt} from './cloud-relay-reporting.js';
import {projectCloudTestScope,ensureProjectCloudTestScope} from './cloud-project-tests.js';

export const CLOUD_TEST_PROTOCOL='harnessd-cloud-test-intent-v1';
export const CLOUD_PROJECT_TEST_PROTOCOL='harnessd-cloud-test-intent-v2';
const UUID=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const HASH=/^[a-f0-9]{64}$/;
const fields=['protocol','requestId','sessionId','generation','grantId','grantRevision',
  'accessRevision','sourceSha','testFiles','prNumber','optionsIssueNumber','issuedAtMs'];
const fail=code=>{throw Object.assign(new Error(code),{code});};
const hash=s=>createHash('sha256').update(s).digest('hex');
export function cloudTestPayload(input){
  const selected=input?.protocol===CLOUD_PROJECT_TEST_PROTOCOL?[...fields,'profile','sourceRef','host']:fields;
  if(!input||typeof input!=='object'||Array.isArray(input)||
    Object.keys(input).sort().join('|')!==selected.slice().sort().join('|')||
    ![CLOUD_TEST_PROTOCOL,CLOUD_PROJECT_TEST_PROTOCOL].includes(input.protocol)||!UUID.test(input.requestId)||!UUID.test(input.sessionId)||
    !HASH.test(input.grantId)||!['generation','grantRevision','accessRevision'].every(k=>Number.isSafeInteger(input[k])&&input[k]>0)||
    !/^[a-f0-9]{40}$/.test(input.sourceSha)||!Number.isSafeInteger(input.issuedAtMs)||input.issuedAtMs<0||
    !['prNumber','optionsIssueNumber'].every(k=>input[k]===null||(Number.isSafeInteger(input[k])&&input[k]>0&&input[k]<=10000000))||
    !(input.testFiles===null||(Array.isArray(input.testFiles)&&input.testFiles.length<=32&&input.testFiles.every(t=>typeof t==='string'&&t.length<=240))))
    fail('CLOUD_TEST_SHAPE');
  if(input.protocol===CLOUD_PROJECT_TEST_PROTOCOL&&['profile','sourceRef','host'].some(k=>typeof input[k]!=='string'||input[k].length>200))fail('CLOUD_TEST_SHAPE');
  return input.protocol+'\n'+JSON.stringify(Object.fromEntries(selected.map(k=>[k,input[k]])))+'\n';
}
export function parseCloudTestIntent(body){
  if(typeof body!=='string'||Buffer.byteLength(body)>10000)return null;
  try{
    const {signature,...input}=JSON.parse(body);
    cloudTestPayload(input);
    if(typeof signature!=='string'||Buffer.from(signature,'base64').length!==64||
      Buffer.from(signature,'base64').toString('base64')!==signature)return null;
    return {...input,signature};
  }catch{return null;}
}
export function ensureCloudTestIntents(state){
  state.db.exec(`CREATE TABLE IF NOT EXISTS cloud_test_intents(
    request_id TEXT PRIMARY KEY,body_json TEXT NOT NULL,body_hash TEXT NOT NULL,
    control_repo TEXT NOT NULL,issue_number INTEGER NOT NULL,created_at INTEGER NOT NULL);
    CREATE TRIGGER IF NOT EXISTS cloud_test_no_update BEFORE UPDATE ON cloud_test_intents
      BEGIN SELECT RAISE(ABORT,'cloud test intent immutable'); END;
    CREATE TRIGGER IF NOT EXISTS cloud_test_no_delete BEFORE DELETE ON cloud_test_intents
      BEGIN SELECT RAISE(ABORT,'cloud test intent immutable'); END;
    CREATE TABLE IF NOT EXISTS cloud_test_progress(
      request_id TEXT PRIMARY KEY,status_json TEXT NOT NULL);`);
}
export function listCloudTestIntents(state){
  if(!state.db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name='cloud_test_intents'").get())return [];
  return state.db.prepare('SELECT * FROM cloud_test_intents ORDER BY created_at,request_id').all()
    .map(r=>({...r,intent:JSON.parse(r.body_json)}));
}
export function authorizeCloudTest(state,intent,{now=Date.now()}={}){
  let grant=currentCloudGrant(state,intent.grantId);
  const projectWide=intent.protocol===CLOUD_PROJECT_TEST_PROTOCOL;
  if(!grant||grant.kind!==(projectWide?'SESSION':'LAB')||grant.action!=='ALLOW'||grant.revision!==intent.grantRevision)
    fail('CLOUD_TEST_GRANT_REVOKED');
  const access=requireCloudAccess(state,projectWide?grant.grantId:grant.scope.accessGrantId,intent.accessRevision);
  if(projectWide)grant={...grant,scope:projectCloudTestScope(state,access,intent)};
  const session=assertCloudSessionCurrent(state,{sessionId:intent.sessionId,generation:intent.generation,now});
  if(session.heartbeatPhase!=='LIVE'||session.projectRepo!==grant.scope.projectRepo||
    session.projectRepo!==access.scope.projectRepo||session.role!==access.scope.role||
    session.agentId!==cloudStableAgentId(access.scope.projectRepo,access.scope.role,access.scope.author))
    fail('CLOUD_TEST_SESSION_SCOPE');
  return {grant,access,session};
}
// Transport authentication remains possible after grant/session expiry so a
// signed original request can receive a refusal without acquiring authority.
export function authenticateCloudTestIntent(state,{intent,comment,controlRepo,issueNumber}){
  const {signature,...input}=intent,payload=cloudTestPayload(input);
  const grant=currentCloudGrant(state,intent.grantId);
  const access=grant?.kind==='SESSION'?grant:currentCloudGrant(state,grant?.scope.accessGrantId);
  if(!access||access.scope.controlRepo!==controlRepo||comment.issueNumber!==issueNumber||
    comment.author?.id!==access.scope.accountId||comment.author?.login?.toLowerCase()!==access.scope.author)
    fail('CLOUD_TEST_AUTHOR');
  const bound=state.db.prepare('SELECT * FROM cloud_registration_bindings WHERE control_repo=? AND issue_number=?')
    .get(controlRepo,issueNumber);
  if(bound?.session_id!==intent.sessionId||bound?.generation!==intent.generation)fail('CLOUD_TEST_ISSUE');
  const row=state.db.prepare('SELECT public_key,project_repo FROM cloud_session_records WHERE session_id=?').get(intent.sessionId);
  if(!row||row.project_repo!==access.scope.projectRepo||!verify(null,Buffer.from(payload),publicKeyFromBase64(row.public_key),Buffer.from(signature,'base64')))
    fail('CLOUD_TEST_SIGNATURE');
  return {input,payload};
}
const has=(state,table)=>Boolean(state.db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").get(table));
export function cloudTestHasCustody(state,requestId){
  return (has(state,'cloud_test_intents')&&Boolean(state.db.prepare('SELECT 1 FROM cloud_test_intents WHERE request_id=?').get(requestId)))||
    (has(state,'lab_test_plans')&&Boolean(state.db.prepare('SELECT 1 FROM lab_test_plans WHERE id=?').get(requestId)))||
    (has(state,'lab_dispatch_outbox')&&Boolean(state.db.prepare('SELECT 1 FROM lab_dispatch_outbox WHERE plan_id=?').get(requestId)))||
    (has(state,'lab_gateway_observations')&&Boolean(state.db.prepare('SELECT 1 FROM lab_gateway_observations WHERE plan_id=?').get(requestId)));
}
function priorTestRefusal(state,requestId){
  if(!has(state,'events'))return null;
  const row=state.db.prepare(`SELECT payload_json FROM events WHERE type='cloud.relay_receipt'
    AND json_extract(payload_json,'$.kind')='test' AND json_extract(payload_json,'$.receipt.requestId')=? ORDER BY id LIMIT 1`).get(requestId);
  return row?JSON.parse(row.payload_json):null;
}
export function retainCloudTestRefusal(state,args,error){
  const {intent,comment,controlRepo,issueNumber,now=Date.now()}=args;
  const {payload}=authenticateCloudTestIntent(state,args);
  const prior=priorTestRefusal(state,intent.requestId);
  if(prior)return prior;
  if(cloudTestHasCustody(state,intent.requestId))return null;
  const allowed=['CLOUD_TEST_GRANT_REVOKED','CLOUD_ACCESS_REVOKED','CLOUD_ACCESS_REVISION',
    'CLOUD_TEST_SESSION_SCOPE','CLOUD_SESSION_FENCED','CLOUD_TEST_STALE','CLOUD_TEST_PROJECT_SCOPE',
    'CLOUD_TEST_LAB_NOT_CONFIGURED','CLOUD_TEST_SELECTION_NOT_CANONICAL',
    'LAB_REPO_TEST_LIST_INVALID','LAB_REPO_TEST_PATH_INVALID','LAB_REPO_TEST_PROFILE_FIXED'];
  const receipt={protocol:'harnessd-cloud-test-status-v1',requestId:intent.requestId,planId:null,
    labRequestId:null,issueNumber:null,status:'REFUSED',outcome:'NOT_RUN',host:null,
    reason:allowed.includes(error?.code)?error.code:'CLOUD_TEST_REFUSED',
    controlIssueNumber:issueNumber,intentCommentId:comment.id,
    intentSha256:hash(payload),recordedAt:new Date(now).toISOString()};
  return retainRelayReceipt(state,{controlRepo,issueNumber,commentId:comment.id},'test',receipt);
}
export function acceptCloudTestIntent(state,{intent,comment,controlRepo,issueNumber,now=Date.now()}={}){
  const {signature}=intent;
  const {input,payload}=authenticateCloudTestIntent(state,{intent,comment,controlRepo,issueNumber});
  const body=JSON.stringify({...input,signature}),digest=hash(payload);
  // Existing custody wins even after the session becomes fenced. This is
  // observational replay only; advancement still rechecks current authority.
  const existing=has(state,'cloud_test_intents')?state.db.prepare('SELECT * FROM cloud_test_intents WHERE request_id=?').get(intent.requestId):null;
  if(existing){if(existing.body_hash!==digest||existing.control_repo!==controlRepo||existing.issue_number!==issueNumber)fail('CLOUD_TEST_ID_CONFLICT');return {alreadyAccepted:true};}
  const refusal=priorTestRefusal(state,intent.requestId);
  if(refusal)fail(refusal.receipt.intentSha256===digest?'CLOUD_TEST_PREVIOUSLY_REFUSED':'CLOUD_TEST_ID_CONFLICT');
  const {grant}=authorizeCloudTest(state,intent,{now});
  ensureCloudTestIntents(state);
  if(Math.abs(now-intent.issuedAtMs)>5*60_000)fail('CLOUD_TEST_STALE');
  // Validate the closed existing selection BEFORE recording any plan.
  const selected=resolveLabRepoTestSelection({projectRepo:grant.scope.projectRepo,profile:grant.scope.profile},intent.testFiles);
  if(JSON.stringify(selected)!==JSON.stringify(intent.testFiles))fail('CLOUD_TEST_SELECTION_NOT_CANONICAL');
  ensureLabTestingSchema(state);
  state.db.exec('SAVEPOINT cloud_test_accept');
  try{
    // An unrelated existing operator plan cannot be claimed by a cloud ID.
    if(state.db.prepare('SELECT 1 FROM lab_test_plans WHERE id=?').get(intent.requestId))fail('CLOUD_TEST_PLAN_CONFLICT');
    if(input.protocol===CLOUD_PROJECT_TEST_PROTOCOL)ensureProjectCloudTestScope(state,grant.scope);
    planLabTest(state,{id:intent.requestId,endeavourId:grant.scope.endeavourId,
      environmentId:grant.scope.environmentId,sourceSha:intent.sourceSha,profile:grant.scope.profile});
    state.db.prepare('INSERT INTO cloud_test_intents VALUES(?,?,?,?,?,?)').run(intent.requestId,body,digest,controlRepo,issueNumber,now);
    state.db.exec('RELEASE cloud_test_accept');
  }catch(e){state.db.exec('ROLLBACK TO cloud_test_accept; RELEASE cloud_test_accept');throw e;}
  return {alreadyAccepted:false};
}
export function cloudTestStatus(state,requestId){
  const dispatch=getLabDispatch(state,requestId);
  const proof=labProofForPlan(state,requestId);
  return {protocol:'harnessd-cloud-test-status-v1',requestId,planId:requestId,
    labRequestId:dispatch?.requestId??null,issueNumber:dispatch?.issueNumber??null,
    status:proof?.status??(dispatch?.status==='SUBMITTED'?'WAITING_FOR_LAB':dispatch?.status??'ACCEPTED'),
    outcome:proof?.outcome??'NOT_RUN',host:dispatch?.host??null};
}
export async function advanceCloudTestIntent(state,row,{dispatch,now=()=>Date.now()}={}){
  const intent=row.intent,authorize=()=>authorizeCloudTest(state,intent,{now:now()});
  let status;
  try{
    let prepared=getLabDispatch(state,intent.requestId);
    if(!prepared){
      const {grant}=authorize();
      await dispatch({op:'lab.dispatchPrepare',planId:intent.requestId,
        host:grant.scope.host,sourceRef:grant.scope.sourceRef,
        testFiles:intent.testFiles,prNumber:intent.prNumber,optionsIssueNumber:intent.optionsIssueNumber},{authorize});
      prepared=getLabDispatch(state,intent.requestId);
    }
    if(prepared.status==='PREPARED')await dispatch({op:'lab.dispatchSubmit',planId:intent.requestId},{authorize});
    prepared=getLabDispatch(state,intent.requestId);
    // Observation survives disconnect/revocation; it cannot start work.
    if(prepared.status==='SUBMITTED'&&!labProofForPlan(state,intent.requestId))
      await dispatch({op:'lab.dispatchObserve',planId:intent.requestId});
    status=cloudTestStatus(state,intent.requestId);
  }catch(error){
    if(['LAB_FLEET_OBSERVATION_PENDING','LAB_FLEET_OBSERVATION_RETRY_WAIT'].includes(error?.code)) {
      // The observer GET/POST was asynchronous. A pending measurement cannot
      // hide a request/session/grant that expired or was revoked meanwhile.
      try{authorize();}catch(authorityError){error=authorityError;}
    }
    status={...cloudTestStatus(state,intent.requestId),
      status:getLabDispatch(state,intent.requestId)?.status==='ACK_UNCERTAIN'?'ACK_UNCERTAIN':
        ['LAB_FLEET_OBSERVATION_PENDING','LAB_FLEET_OBSERVATION_RETRY_WAIT'].includes(error?.code)?'WAITING_FOR_FLEET':'ATTENTION',
      reason:/^[A-Z][A-Z0-9_]{0,99}$/.test(error?.code??'')?error.code:'CLOUD_TEST_UNAVAILABLE'};
  }
  state.db.prepare('INSERT INTO cloud_test_progress VALUES(?,?) ON CONFLICT(request_id) DO UPDATE SET status_json=excluded.status_json')
    .run(intent.requestId,JSON.stringify(status));
  return status;
}

import {publishRelayReceipts} from './cloud-relay-reporting.js';
import {cloudGuidanceDeliveries,authorizeCloudGuidanceDelivery,parseCloudGuidanceReply,acceptCloudGuidanceReply} from './cloud-guidance.js';
// Runs inside the existing daemon poll. GitHub is transport; durable grants,
// cloud proof/session owners and M10 remain the only authorities.
import {createHash} from 'node:crypto';
import {configuredCloudControlRepo} from './cloud-agent-onboarding.js';
import {cloudAccessForIssue,listCloudGrants} from './cloud-project-access.js';
import {parseCloudRegistrationIntent} from './cloud-agent-registration-intents.js';
import {approveCloudRegistrationIntent,readCloudHumanApproval} from './cloud-human-approval.js';
import {stageApprovedCloudChallenge,activateApprovedCloudSession,publishCloudSessionReceipt,cloudSessionAttachmentForIssue} from './cloud-agent-gateway.js';
import {parseCloudTestIntent,acceptCloudTestIntent,listCloudTestIntents,advanceCloudTestIntent,retainCloudTestRefusal,cloudTestHasCustody} from './cloud-test-intents.js';
import {knownLabDispatchProfiles} from './lab-shared-dispatch-contract.js';
import {labProofForPlan} from './lab-proof-history.js';

const cursors=new WeakMap();
const sha=s=>createHash('sha256').update(s).digest('hex');
const has=(state,table)=>Boolean(state.db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").get(table));
const parse=body=>{try{return JSON.parse(body);}catch{return null;}};
function rotation(items,offset,count=4){
  return Array.from({length:Math.min(count,items.length)},(_,i)=>items[(offset+i)%items.length]);
}
export async function processCloudWorkRelay(state,{transport,dispatch,
  environment=process.env,now=()=>Date.now(),minRecheckMs=30000,signal=null}={}){
  const before=cursors.get(state.db)??{at:-Infinity,issues:0,jobs:0,fenced:0};
  if(now()-before.at<minRecheckMs||!transport)return {skipped:true};
  const grants=listCloudGrants(state),jobs=listCloudTestIntents(state);
  if(!grants.length&&!jobs.length)return {skipped:true};
  const repo=configuredCloudControlRepo(environment);
  const summary={attached:0,accepted:0,observed:0,refused:0,unavailable:0};
  const exact={issue:(r,n)=>transport.getCloudRegistrationIssue(r,n,{signal}),
    comment:(r,n,id)=>transport.getCloudRegistrationComment(r,n,id,{signal}),
    comments:(r,n)=>transport.listCloudRegistrationComments(r,n,{signal}),
    post:(r,n,b,beforePost=null)=>transport.postCloudRegistrationComment(r,n,b,{signal,beforePost})};
  let issues=[];
  try{issues=await transport.listOpenIssues(repo,{signal});}catch{summary.unavailable++;}
  if(!Array.isArray(issues)||issues.length>2000)issues=[];
  const candidates=issues.filter(issue=>{
    if(!cloudAccessForIssue(state,issue,repo))return false;
    if(!has(state,'cloud_registration_bindings'))return true;
    const bound=state.db.prepare(`SELECT s.status,s.lease_until_ms FROM cloud_registration_bindings b
      LEFT JOIN cloud_session_records s ON s.session_id=b.session_id
      WHERE b.control_repo=? AND b.issue_number=?`).get(repo,issue.number);
    return !bound||(bound.status==='ACTIVE'&&bound.lease_until_ms>now());
  });
  // Finish the short-lived challenges we already issued before starting more.
  // Historical sessions never compete with live handshakes; their lab jobs
  // are observed below independently. This is bounded ingress, not scheduling.
  const staged=has(state,'cloud_proof_challenges')?state.db.prepare(`SELECT c.issue_number,MIN(c.expires_at_ms) deadline
    FROM cloud_proof_challenges c LEFT JOIN cloud_proof_consumptions p ON p.challenge_id=c.challenge_id
    WHERE c.control_repo=? AND c.expires_at_ms>? AND p.challenge_id IS NULL
    GROUP BY c.issue_number ORDER BY deadline`).all(repo,now()):[];
  const pending=staged.map(r=>candidates.find(i=>i.number===r.issue_number)).filter(Boolean).slice(0,4);
  const selected=[...pending,...rotation(candidates.filter(i=>!pending.some(p=>p.number===i.number)),before.issues,4-pending.length)];
  cursors.set(state.db,{at:now(),issues:before.issues+selected.length,jobs:before.jobs+4,fenced:(before.fenced??0)+4});
  for(const listed of selected){
    if(signal?.aborted)break;
    try{
      const issue=await exact.issue(repo,listed.number);
      const grant=cloudAccessForIssue(state,issue,repo);
      if(!grant)continue;
      const intent=parseCloudRegistrationIntent(issue,{controlRepo:repo,hasProject:r=>Boolean(state.getProject(r)?.enabled)});
      if(!intent)continue;
      let comments=await exact.comments(repo,issue.number);
      if(!Array.isArray(comments)||comments.length>400)continue;
      let binding=has(state,'cloud_registration_bindings')?state.db.prepare(
        'SELECT * FROM cloud_registration_bindings WHERE control_repo=? AND issue_number=?').get(repo,issue.number):null;
      if(!binding){
        // Fresh proof, inherited authority: immutable receipt names the exact
        // standing grant revision. It never pretends a new human clicked.
        const approval=readCloudHumanApproval(state,{issueNumber:issue.number,environment})??
          approveCloudRegistrationIntent(state,{issue,approvedCapabilities:JSON.parse(issue.body).capabilities,
            expectedIssueBodySha256:sha(issue.body),standingGrant:grant,environment,now:now()});
        const nonce=JSON.parse(issue.body).nonce;
        const owned=comments.filter(c=>c.author?.id===grant.scope.accountId&&
          c.author?.login?.toLowerCase()===grant.scope.author&&c.issueNumber===issue.number);
        const keys=owned.filter(c=>{const p=parse(c.body);return p?.protocol==='harnessd-cloud-key-v1'&&p.registrationNonce===nonce;});
        if(keys.length!==1)continue;
        const challenge=await stageApprovedCloudChallenge(state,{issueNumber:issue.number,keyCommentId:keys[0].id,
          expectedIssueBodySha256:approval.issueBodySha256,transport:exact,environment,now:now()});
        const proofs=owned.filter(c=>{const p=parse(c.body);return p?.protocol==='harnessd-cloud-proof-v1'&&p.challengeId===challenge.challengeId;});
        if(proofs.length!==1)continue;
        const session=await activateApprovedCloudSession(state,{issueNumber:issue.number,keyCommentId:keys[0].id,
          proofCommentId:proofs[0].id,challengeId:challenge.challengeId,transport:exact,environment,now:now()});
        summary.attached++;
        binding={session_id:session.sessionId,generation:session.generation};
      }
      // A committed attachment with a lost reply must be publishable on the
      // next poll without consuming a second proof or registering a session.
      await publishCloudSessionReceipt(cloudSessionAttachmentForIssue(state,repo,issue.number),{transport:exact,environment});
      const available=listCloudGrants(state).filter(g=>g.kind==='LAB'&&g.action==='ALLOW'&&g.scope.accessGrantId===grant.grantId);
      const permissions=JSON.stringify({protocol:'harnessd-cloud-test-grants-v1',sessionId:binding.session_id,
        generation:binding.generation,accessRevision:grant.revision,
        projectWork:grant.scope.projectWork===true?{grantId:grant.grantId,grantRevision:grant.revision,projectRepo:grant.scope.projectRepo,profiles:knownLabDispatchProfiles()[grant.scope.projectRepo]??[]}:null,
        grants:available.slice(0,4).map(g=>({grantId:g.grantId,grantRevision:g.revision,profile:g.scope.profile,
          sourceRef:g.scope.sourceRef,host:g.scope.host})),truncated:available.length>4});
      if(!comments.some(c=>c.body===permissions))await exact.post(repo,issue.number,permissions);
      for(const delivery of cloudGuidanceDeliveries(state,{controlRepo:repo,issueNumber:issue.number,now:now()})){
        // Comments were fetched asynchronously. Recheck immediately before POST.
        authorizeCloudGuidanceDelivery(state,delivery.id,{now:now()});
        if(!comments.some(c=>c.body===delivery.body))await exact.post(repo,issue.number,delivery.body,()=>authorizeCloudGuidanceDelivery(state,delivery.id,{now:now()}));
      }
      for(const comment of comments){
        const reply=parseCloudGuidanceReply(comment.body);
        if(reply){
          try{acceptCloudGuidanceReply(state,{reply,comment,controlRepo:repo,issueNumber:issue.number,now:now()});}
          catch{summary.refused++;}
          continue;
        }
        const input=parseCloudTestIntent(comment.body);
        if(!input||input.sessionId!==binding.session_id||input.generation!==binding.generation)continue;
        try{
          const accepted=acceptCloudTestIntent(state,{intent:input,comment,controlRepo:repo,issueNumber:issue.number,now:now()});
          if(!accepted.alreadyAccepted)summary.accepted++;
        }catch(error){
          summary.refused++;
          try{retainCloudTestRefusal(state,{intent:input,comment,controlRepo:repo,issueNumber:issue.number,now:now()},error);}catch{/* Unauthenticated input gets no reflective receipt. */}
        }
      }
    }catch{summary.refused++;}
  }
  // A late signed intent may first be seen after its session expired. Inspect
  // only retained bound mailboxes, in a separate bounded observational batch;
  // this path can report refusal but cannot accept or dispatch work.
  const fenced=has(state,'cloud_registration_bindings')&&has(state,'cloud_session_records')?
    state.db.prepare(`SELECT b.issue_number,b.session_id,b.generation FROM cloud_registration_bindings b
      JOIN cloud_session_records s ON s.session_id=b.session_id AND s.generation=b.generation
      WHERE b.control_repo=? AND (s.status!='ACTIVE' OR s.lease_until_ms<=?) ORDER BY b.issue_number`).all(repo,now()):[];
  for(const bound of rotation(fenced,before.fenced??0)){
    if(signal?.aborted)break;
    try{
      const comments=await exact.comments(repo,bound.issue_number);
      if(!Array.isArray(comments)||comments.length>400)continue;
      for(const comment of comments){
        const input=parseCloudTestIntent(comment.body);
        if(!input||input.sessionId!==bound.session_id||input.generation!==bound.generation)continue;
        try{retainCloudTestRefusal(state,{intent:input,comment,controlRepo:repo,issueNumber:bound.issue_number,now:now()},
          {code:'CLOUD_SESSION_FENCED'});}catch{/* Unauthenticated input is never reflected. */}
      }
    }catch{summary.unavailable++;}
  }
  // Accepted jobs are independent of active sessions/open registration issues.
  // The controller continues; the cloud session need not stay online to watch.
  const pendingJobs=listCloudTestIntents(state).filter(row=>{
    const previous=has(state,'cloud_test_progress')?state.db.prepare('SELECT status_json FROM cloud_test_progress WHERE request_id=?').get(row.request_id):null;
    const p=previous?parse(previous.status_json):null;
    return !p?.relayedTerminal;
  });
  for(const row of dispatch ? rotation(pendingJobs,before.jobs) : []){
    if(signal?.aborted)break;
    const status=await advanceCloudTestIntent(state,row,{dispatch,now});
    summary.observed++;
    try{
      const body=JSON.stringify(status);
      const comments=await exact.comments(row.control_repo,row.issue_number);
      // This exact body was derived from local outbox/history above. Finding
      // identical bytes avoids duplicate informational replies after lost ACK;
      // an incoming status comment never supplies execution/proof authority.
      if(!comments.some(c=>c.body===body))
        await exact.post(row.control_repo,row.issue_number,body);
      if(labProofForPlan(state,row.request_id))state.db.prepare('UPDATE cloud_test_progress SET status_json=? WHERE request_id=?')
        .run(JSON.stringify({...status,relayedTerminal:true}),row.request_id);
    }catch{summary.unavailable++;}
  }
  await publishRelayReceipts(state,{controlRepo:repo,comments:exact.comments,post:exact.post,kind:'test',signal,
    shouldPublish:receipt=>!cloudTestHasCustody(state,receipt.requestId)});
  return summary;
}

// One bounded observer outbox through the existing private lab controller.
// No timers, SSH, source requests or execution authorization. Callers advance
// this on the existing daemon/operator turn and preserve original test IDs.
import {createHash,randomBytes} from 'node:crypto';
import {inspectLabResultEnvelope} from './lab-shared-dispatch-result.js';
import {summarizeLagrangeFleet} from './lab-fleet-projection.js';
const fail=code=>{throw Object.assign(new Error(code),{code});};
const canonical=x=>JSON.stringify(Object.fromEntries(Object.entries(x).sort(([a],[b])=>a<b?-1:a>b?1:0)));
const hash=x=>createHash('sha256').update(x).digest('hex');
const iso=ms=>new Date(ms).toISOString().replace(/\.000Z$/,'Z');
const SHA=/^[a-f0-9]{64}$/;
const time=x=>typeof x==='number'&&Number.isSafeInteger(x)?x:Date.parse(x);
function ensure(state) {
  state.db.exec(`CREATE TABLE IF NOT EXISTS lab_fleet_observations(
    request_id TEXT PRIMARY KEY, controller_id TEXT NOT NULL,
    request_json TEXT NOT NULL,request_sha256 TEXT NOT NULL,
    phase TEXT NOT NULL CHECK(phase IN ('PREPARED','ACK_UNCERTAIN','SUBMITTED','COMPLETE','FAILED','REFUSED','UNCERTAIN')),
    issue_number INTEGER UNIQUE,result_json TEXT,updated_at INTEGER NOT NULL);
    CREATE TRIGGER IF NOT EXISTS lab_fleet_observation_identity BEFORE UPDATE ON lab_fleet_observations
      WHEN NEW.request_id<>OLD.request_id OR NEW.controller_id<>OLD.controller_id OR
      NEW.request_json<>OLD.request_json OR NEW.request_sha256<>OLD.request_sha256 OR
      (OLD.issue_number IS NOT NULL AND NEW.issue_number IS NOT OLD.issue_number) OR
      (OLD.result_json IS NOT NULL AND NEW.result_json IS NOT OLD.result_json) OR
      (NEW.phase<>OLD.phase AND NOT (
        (OLD.phase='PREPARED' AND NEW.phase IN ('ACK_UNCERTAIN','REFUSED')) OR
        (OLD.phase='ACK_UNCERTAIN' AND NEW.phase='SUBMITTED') OR
        (OLD.phase='SUBMITTED' AND NEW.phase IN ('COMPLETE','FAILED','REFUSED','UNCERTAIN'))))
      BEGIN SELECT RAISE(ABORT,'fleet observation identity immutable'); END;
    CREATE TRIGGER IF NOT EXISTS lab_fleet_observation_no_delete BEFORE DELETE ON lab_fleet_observations
      BEGIN SELECT RAISE(ABORT,'fleet observation history immutable'); END;`);
}
function dispatchRow(row) {
  return {status:'SUBMITTED',issueNumber:row.issue_number,requestId:row.request_id,
    requestSha256:row.request_sha256,request:JSON.parse(row.request_json)};
}
export function verifiedFleetObservation(row,observation,{controllerId,publisherLogin,now}) {
  if(observation?.repo!=='psvensson/lagrange-lab')fail('LAB_FLEET_RECEIPT_REPO');
  const {receipt}=inspectLabResultEnvelope({dispatch:dispatchRow(row),...observation,controllerId,publisherLogin});
  if(!receipt)return null;
  if(receipt.status!=='COMPLETE')return {phase:receipt.status,receipt};
  const r=receipt.result;
  let fleet;try{fleet=JSON.parse(r?.fleet_json);}catch{fail('LAB_FLEET_RECEIPT_INVALID');}
  const start=Date.parse(r?.observed_started_at),end=Date.parse(r?.observed_completed_at);
  const recorded=Date.parse(receipt.recorded_at),request=JSON.parse(row.request_json);
  if(r?.protocol!=='lagrange-lab-fleet-observation-v1'||r.operation!=='lab-fleet-observe'||
      r.source_execution_started!==false||r.observer_scope_closed!==true||!SHA.test(r.raw_stdout_sha256??'')||typeof r.fleet_json!=='string'||Buffer.byteLength(r.fleet_json)>32_000||!Array.isArray(fleet)||fleet.length>128||
      !/^[a-f0-9]{40}$/.test(r.collector_source_sha??'')||!SHA.test(r.collector_node_sha256??'')||
      !SHA.test(r.fleet_sha256??'')||hash(r.fleet_json)!==r.fleet_sha256||
      !Number.isFinite(start)||!Number.isFinite(end)||!Number.isFinite(recorded)||
      start<Date.parse(request.created_at)||start>=Date.parse(request.expires_at)||
      end<start||end-start>90_000||end>now+2000||recorded<Math.floor(end/1000)*1000||recorded>now+2000)
    fail('LAB_FLEET_RECEIPT_INVALID');
  // Require actual native host timestamps and boot IDs; never infer them from
  // HTTP/comment delivery time. Error entries stay unavailable, not green.
  for(const item of fleet)if(item?.capability && (!Number.isFinite(time(item.capability.probedAt))||
      typeof item.capability.bootId!=='string'||!item.capability.bootId||
      time(item.capability.probedAt)<start||time(item.capability.probedAt)>end))
    fail('LAB_FLEET_RECEIPT_HOST_IDENTITY');
  return {phase:'COMPLETE',receipt};
}
export function createLabFleetGatewayReader({readTransport,writeTransport,now=()=>Date.now(),newId=()=>randomBytes(16).toString('hex')}={}) {
  if(!/^[a-f0-9]{32}$/.test(readTransport?.controllerId??'')||
      typeof readTransport.readIssueWithComments!=='function'||
      typeof readTransport.findIssuesByRequestId!=='function'||
      typeof writeTransport?.createIssue!=='function'||typeof writeTransport.verifyReadiness!=='function')
    fail('LAB_FLEET_GATEWAY_NOT_CONFIGURED');
  const controllerId=readTransport.controllerId,publisherLogin=readTransport.publisherLogin;
  let inFlight=null;
  async function advance(state) {
    if(state.getProject?.('psvensson/lagrange')?.enabled!==1)fail('LAB_FLEET_PROJECT_NOT_REGISTERED');
    ensure(state);
    let row=state.db.prepare('SELECT * FROM lab_fleet_observations WHERE controller_id=? ORDER BY rowid DESC LIMIT 1').get(controllerId);
    const clock=now();
    if(row?.phase==='UNCERTAIN')fail('LAB_FLEET_OBSERVATION_UNCERTAIN');
    if(row?.phase==='COMPLETE') {
      const r=JSON.parse(row.result_json).result;
      const snapshot=summarizeLagrangeFleet(JSON.parse(r.fleet_json),{observedAt:r.observed_completed_at,now:iso(clock)});
      if(snapshot.fresh)return {...snapshot,observationProof:{issueNumber:row.issue_number,requestSha256:row.request_sha256,requestId:row.request_id}};
    }
    if(!row||['COMPLETE','FAILED','REFUSED'].includes(row.phase)) {
      if(row&&clock-row.updated_at<30_000)fail('LAB_FLEET_OBSERVATION_RETRY_WAIT');
      const request={schema:'lagrange-lab-job/v1',controller_id:controllerId,request_id:newId(),
        operation:'lab-fleet-observe',created_at:iso(clock),expires_at:iso(clock+300_000)};
      if(!/^[a-f0-9]{32}$/.test(request.request_id))fail('LAB_FLEET_OBSERVATION_ID_INVALID');
      const bytes=canonical(request);
      state.db.prepare('INSERT INTO lab_fleet_observations VALUES(?,?,?,?,?,?,?,?)')
        .run(request.request_id,controllerId,bytes,hash(bytes),'PREPARED',null,null,clock);
      row=state.db.prepare('SELECT * FROM lab_fleet_observations WHERE request_id=?').get(request.request_id);
    }
    if(row.phase==='PREPARED') {
      if(now()>=Date.parse(JSON.parse(row.request_json).expires_at)) {
        // No POST transition ever occurred. This original expired identity is
        // safely retired, unlike ACK_UNCERTAIN or a submitted missing result.
        state.db.prepare("UPDATE lab_fleet_observations SET phase='REFUSED',updated_at=? WHERE request_id=? AND phase='PREPARED'").run(now(),row.request_id);
        fail('LAB_FLEET_OBSERVATION_RETRY_WAIT');
      }
      await writeTransport.verifyReadiness();
      if(state.getProject('psvensson/lagrange')?.enabled!==1)fail('LAB_FLEET_PROJECT_NOT_REGISTERED');
      if(now()>=Date.parse(JSON.parse(row.request_json).expires_at))fail('LAB_FLEET_OBSERVATION_EXPIRED');
      state.db.prepare("UPDATE lab_fleet_observations SET phase='ACK_UNCERTAIN',updated_at=? WHERE request_id=? AND phase='PREPARED'").run(now(),row.request_id);
      let issue;
      try { issue=await writeTransport.createIssue('psvensson/lagrange-lab','[lab-job] '+row.request_id,row.request_json,{beforePost:()=>{
        if(state.getProject('psvensson/lagrange')?.enabled!==1||now()>=Date.parse(JSON.parse(row.request_json).expires_at))fail('LAB_FLEET_OBSERVATION_AUTHORITY_CHANGED');
      }}); }catch{fail('LAB_FLEET_OBSERVATION_ACK_UNCERTAIN');}
      attach(state,row,issue);
      fail('LAB_FLEET_OBSERVATION_PENDING');
    }
    if(row.phase==='ACK_UNCERTAIN') {
      const matches=await readTransport.findIssuesByRequestId(row.request_id);
      if(matches.length!==1)fail('LAB_FLEET_OBSERVATION_ACK_UNCERTAIN');
      attach(state,row,matches[0]);
      row=state.db.prepare('SELECT * FROM lab_fleet_observations WHERE request_id=?').get(row.request_id);
    }
    const observed=await readTransport.readIssueWithComments('psvensson/lagrange-lab',row.issue_number);
    const verified=verifiedFleetObservation(row,observed,{controllerId,publisherLogin,now:now()});
    if(!verified)fail(now()>=Date.parse(JSON.parse(row.request_json).expires_at)?'LAB_FLEET_OBSERVATION_EXPIRED':'LAB_FLEET_OBSERVATION_PENDING');
    state.db.prepare('UPDATE lab_fleet_observations SET phase=?,result_json=?,updated_at=? WHERE request_id=? AND result_json IS NULL')
      .run(verified.phase,JSON.stringify(verified.receipt),now(),row.request_id);
    if(verified.phase!=='COMPLETE')fail(verified.phase==='UNCERTAIN'?'LAB_FLEET_OBSERVATION_UNCERTAIN':'LAB_FLEET_OBSERVATION_UNAVAILABLE');
    const r=verified.receipt.result,snapshot=summarizeLagrangeFleet(JSON.parse(r.fleet_json),{observedAt:r.observed_completed_at,now:iso(now())});
    if(!snapshot.fresh)fail('LAB_FLEET_OBSERVATION_STALE');
    return {...snapshot,observationProof:{issueNumber:row.issue_number,requestSha256:row.request_sha256,requestId:row.request_id}};
  }
  function attach(state,row,issue) {
    if(!Number.isSafeInteger(issue?.number)||issue.number<1||issue.number>10_000_000||
      issue.title!=='[lab-job] '+row.request_id||
      (issue.user&&issue.user.login!==publisherLogin))fail('LAB_FLEET_OBSERVATION_ACK_UNTRUSTED');
    let body;try{body=canonical(JSON.parse(issue.body));}catch{fail('LAB_FLEET_OBSERVATION_ACK_UNTRUSTED');}
    if(body!==row.request_json)fail('LAB_FLEET_OBSERVATION_ACK_UNTRUSTED');
    state.db.prepare("UPDATE lab_fleet_observations SET phase='SUBMITTED',issue_number=?,updated_at=? WHERE request_id=? AND phase='ACK_UNCERTAIN'").run(issue.number,now(),row.request_id);
  }
  return Object.freeze({refresh(state){
    if(inFlight)return inFlight;
    inFlight=advance(state).finally(()=>{inFlight=null;});return inFlight;
  }});
}

// Observational projection of Lagrange's existing "lab fleet --json" output.
// Machine availability is independent of the producing project's dependency
// readiness. Neither is a test execution grant or substitute for the shared
// host lock and thermal owner at actual admission.
const LOCKS=new Set(['free','busy','stale-record','unknown']);
const TOOL_NAMES=['git','docker','helm','wasm-tools','psql','g++','java','rg','jq'];
const isObject=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
const text=x=>typeof x==='string'?x.slice(0,160):null;
const number=x=>typeof x==='number'&&Number.isFinite(x)&&x>=0?x:null;
const millis=x=>typeof x==='number'&&Number.isSafeInteger(x)&&x>=0?x:
  typeof x==='string'&&Number.isFinite(Date.parse(x))?Date.parse(x):null;
const fail=code=>{throw Object.assign(new Error(code),{code});};

export function summarizeLagrangeFleet(fleet,{
  observedAt=null,now=new Date().toISOString(),maxAgeMs=60_000,
}={}) {
  if(!Array.isArray(fleet)||fleet.length>128||!fleet.every(isObject))
    fail('LAB_FLEET_OBSERVATION_INVALID');
  const observed=millis(observedAt),clock=millis(now);
  const fresh=observed!==null&&clock!==null&&
    Number.isSafeInteger(maxAgeMs)&&maxAgeMs>=1&&maxAgeMs<=300_000&&
    observed<=clock+2000&&clock-observed<=maxAgeMs;
  const reference=fleet.find(e=>e.controller===true)?.capability?.cpuSampleMs;
  const seenNames=new Set(),seenBootIds=new Set();
  return Object.freeze({
    source:'lagrange-lab-fleet-json-v1',observedAt,fresh,
    schedulingAuthority:'HARNESSD_EXISTING_OWNER_ONLY',
    projectReadinessSource:'psvensson/lagrange',
    records:fleet.map(item=>{
      const name=text(item.name);
      const cap=isObject(item.capability)?item.capability:null;
      const bootId=text(cap?.bootId);
      const alias=(name!==null&&seenNames.has(name)) ||
        Boolean(item.sameMachineAs) ||
        (bootId!==null&&seenBootIds.has(bootId));
      if(name!==null)seenNames.add(name);
      if(bootId!==null)seenBootIds.add(bootId);
      const lock=isObject(cap?.machineLock)?cap.machineLock:null;
      const lockState=LOCKS.has(lock?.state)?lock.state:'unknown';
      const probeMs=millis(cap?.probedAt);
      // If per-host probe time exists, it cannot be older than the fleet
      // observation budget or beyond the future skew tolerance.
      const sampleFresh=fresh&&(probeMs===null ||
        probeMs<=clock+2000&&clock-probeMs<=maxAgeMs);
      const reachable=cap!==null&&!item.error&&!alias&&Boolean(name);
      const physicalState=!sampleFresh?'STALE':
        item.error?'UNREACHABLE':alias?'DUPLICATE':
          !reachable?'UNKNOWN':lockState==='busy'?'BUSY':
            lockState==='free'?'FREE':'UNKNOWN';
      const hardwareAvailable=physicalState==='FREE';
      const ready=item.readiness?.ready===true;
      const projectStatus=ready?'READY':
        item.readiness?.ready===false?'NOT_READY':'UNKNOWN';
      const reason=!sampleFresh?'STALE_PROBE':
        item.error?'UNREACHABLE':alias?'SAME_PHYSICAL_MACHINE':
          !reachable?'CAPABILITY_MISSING':
            lockState==='busy'?'MACHINE_LOCK_HELD':
              lockState!=='free'?'LOCK_STATE_UNKNOWN':
                !ready?'PROJECT_READINESS_REFUSED':
                  'FINAL_HOST_ADMISSION_REQUIRED';
      const tools={};
      for(const key of TOOL_NAMES)tools[key]=typeof cap?.tools?.[key]==='boolean'
        ?cap.tools[key]:null;
      const speedReference=number(reference),sample=number(cap?.cpuSampleMs);
      const speedFactor=speedReference>0&&sample>0?
        Math.round(sample/speedReference*100)/100:null;
      const missing=Array.isArray(item.readiness?.missing)?
        item.readiness.missing.slice(0,32).filter(x=>typeof x==='string').map(x=>x.slice(0,100)):[];
      const gaps=Array.isArray(item.readiness?.gaps)?
        item.readiness.gaps.slice(0,32).filter(x=>typeof x==='string').map(x=>x.slice(0,100)):[];
      return Object.freeze({
        name,controller:item.controller===true,sameMachineAs:text(item.sameMachineAs),
        machineStatus:physicalState,
        hardwareAvailable,lock:lockState,
        lockHolderProject:text(lock?.holder?.project),
        lockHolderPurpose:text(lock?.holder?.purpose),
        lockHolderAgent:text(lock?.holder?.agent),
        // Lagrange-only readiness MUST NOT disqualify other projects.
        projectReadiness:projectStatus,
        projectReadinessSource:'psvensson/lagrange',
        readiness:ready?'REPORTED_READY':'NOT_REPORTED_READY',
        missing,gaps,
        candidate:hardwareAvailable&&ready,
        reason,
        cores:number(cap?.cores),memKiB:number(cap?.memKiB),
        speedFactor,cpuSampleMs:sample,nodeVersion:text(cap?.nodeVersion),
        toolchain:tools,dockerReachable:cap?.dockerReachable===true,
        repositoryHead:text(cap?.repo?.head),
        repositoryPresent:cap?.repo?.present===true,
        dependenciesCurrent:cap?.repo?.dependenciesCurrent===true,
        capturedAt:probeMs===null?null:new Date(probeMs).toISOString(),
        observedError:typeof item.error==='string'?'PROBE_UNAVAILABLE':null,
        thermal:'NOT_OBSERVED_BY_FLEET',
        finalAdmission:'EXISTING_HOST_LOCK_AND_THERMAL_OWNER',
        authorizedForProject:false,
      });
    }),
  });
}
